use uuid::Uuid;

use crate::domain::{
    models::entity_ingestion::IngestionKey,
    repositories::entity_ingestion::EntitySearchPipelineError,
};

/// File system pipeline
#[derive(Clone)]
pub struct ExposedDataPipeline {
    root: PathBuf,
    key: PipelineKey,
    fs_schema: FsSchema,
}

#[derive(Clone)]
pub struct PipelineKey(Uuid);

impl PipelineKey {
    pub fn new() -> Self {
        Self(Uuid::now_v7())
    }
}

impl From<&PipelineKey> for IngestionKey {
    fn from(value: &PipelineKey) -> Self {
        Self::new(value.0)
    }
}

impl From<IngestionKey> for PipelineKey {
    fn from(value: IngestionKey) -> Self {
        Self(value.uuid())
    }
}

#[derive(Clone)]
struct FsSchema {
    raw: String,
    // cleaned: String,
    // resolved: String,
}

impl Default for FsSchema {
    fn default() -> Self {
        Self {
            raw: "raw".into(),
            // cleaned: "cleaned".into(),
            // resolved: "resolved".into(),
        }
    }
}

impl ExposedDataPipeline {
    /// Returns the absolute path and key of the most recently modified run directory.
    /// Equal timestamps use the greatest UUID. An absent or empty store returns `None`.
    /// This operation does not create or change files.
    ///
    /// # Errors
    /// Returns an error if ingestion storage cannot be read.
    pub async fn latest_ingestion(
        root: &Path,
    ) -> Result<Option<(PathBuf, IngestionKey)>, EntitySearchPipelineError> {
        let root = path::absolute(root).map_err(|e| read_error(root, e))?;
        let mut entries = match fs::read_dir(&root).await {
            Ok(entries) => entries,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(read_error(&root, error)),
        };
        let mut latest: Option<(SystemTime, PathBuf, IngestionKey)> = None;
        while let Some(entry) = entries
            .next_entry()
            .await
            .map_err(|e| read_error(&root, e))?
        {
            let path = entry.path();
            if !entry
                .file_type()
                .await
                .map_err(|e| read_error(&path, e))?
                .is_dir()
            {
                continue;
            }
            let Some(key) = entry
                .file_name()
                .to_str()
                .and_then(|name| name.parse::<IngestionKey>().ok())
            else {
                continue;
            };
            let modified_at = entry
                .metadata()
                .await
                .and_then(|metadata| metadata.modified())
                .map_err(|e| read_error(&path, e))?;
            if latest.as_ref().is_none_or(|(latest_time, _, latest_key)| {
                (modified_at, key.uuid()) > (*latest_time, latest_key.uuid())
            }) {
                latest = Some((modified_at, path, key));
            }
        }
        Ok(latest.map(|(_, path, key)| (path, key)))
    }

    /// Creates a new instance of [`ExposedDataPipeline`] with an [`IngestionKey`]
    ///
    /// # Errors
    /// - if [`root`] cannot be parsed as absolute
    /// - if required directories cannot be created
    pub fn new_with_ingestion_key(
        root: &PathBuf,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let root_abs = path::absolute(root).map_err(|_| {
            EntitySearchPipelineError::Unexpected("valid root path must be provided".to_string())
        })?;

        let res = Self {
            root: root_abs,
            key: PipelineKey::from(key),
            fs_schema: FsSchema::default(),
        };
        std::fs::create_dir_all(res.raw_path()).map_err(|_| {
            EntitySearchPipelineError::Unexpected("must be able to create fs paths".to_string())
        })?;
        Ok(res)
    }

    fn latest_run_path(&self) -> PathBuf {
        self.root.join(self.key.0.to_string())
    }

    pub(super) fn raw_path(&self) -> PathBuf {
        self.latest_run_path().join(&self.fs_schema.raw)
    }

    pub(super) const fn key(&self) -> &PipelineKey {
        &self.key
    }

    // pub(super) fn cleaned_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.cleaned)
    // }
    //
    // pub(super) fn resolved_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.resolved)
    // }
}

fn read_error(path: &Path, error: impl std::fmt::Display) -> EntitySearchPipelineError {
    EntitySearchPipelineError::ReadError(format!("{}: {error}", path.display()))
}

pub(super) fn members_schema() -> Schema {
    let pmi = Field::new("parliament_member_id", DataType::UInt32, false);
    let n = Field::new("name", DataType::Utf8, false);
    let pi = Field::new("party_id", DataType::UInt32, false);
    let pn = Field::new("party_name", DataType::Utf8, false);
    let c = Field::new("constituency", DataType::Utf8, false);
    Schema::new(vec![pmi, n, pi, pn, c])
}
//! Integration test for the entity seacrh endpoint.
//! This test suite expects a pre-loaded database.
//!
//!

use std::{collections::HashMap, ffi::OsString, fs, process::Command, time::Duration};

use anyhow::Context;
use clap::Parser;
use exposed::{
    domain::{
        models::{entity_ingestion::IngestionKey, entity_search::EntitySearchRequest},
        repositories::parliament_member_repository::ParliamentMemberRepo,
    },
    inbound::cli::{DataArgs, run_cli},
    outbound::ExposedDatabase,
};
use sqlx::{ConnectOptions, PgPool};
use tempfile::TempDir;
use tokio::time;

use crate::common::{
    DeclarationFunding, FundingEntry, cli_declaration_fetcher_config, cli_fetcher_config,
    cli_loader_config, read_declaration_funding, search_entities, start_app,
};

mod common;

#[tokio::test]
async fn shows_no_hsbc_duplicates() {
    let app = start_app().await.unwrap();
    time::sleep(Duration::from_secs(2)).await;

    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
    let entities = search_entities(&app, &known_duplicate).await.unwrap();

    let mut duplicates: HashMap<String, usize> = HashMap::new();
    for e in entities.into_iter() {
        duplicates
            .entry(e.get("name").unwrap().as_str().unwrap().into())
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
}

#[sqlx::test(migrations = "../db/migrations")]
async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new().unwrap();

    let (_file, path) = cli_fetcher_config(&tmp);
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "fetch".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_loader_config(&tmp);
    // The process environment must override a URL in .env.
    fs::write(tmp.path().join(".env"), "DATABASE_URL=invalid-url\n").unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(tmp.path())
        .env("DATABASE_URL", url.as_str())
        .args(["data", "members", "load"])
        .arg(path)
        .args(["--ingestion-key", &ingestion_key.to_string()])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );

    let url = pool.connect_options().to_url_lossy();
    let db = ExposedDatabase::new(url.as_str()).await;

    let params =
        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
    let res = db.get_members_by_text_search_score(&params).await.unwrap();

    let (mp, _) = res.first().unwrap();
    assert_eq!(mp.name(), "John McDonnell".to_string());

    Ok(())
}

#[sqlx::test(migrations = "../db/migrations")]
async fn declaration_fetch_preserves_member_funding(pool: PgPool) -> anyhow::Result<()> {
    let members = sqlx::query!(
        "INSERT INTO exposed.members
            (parliament_member_id, name, party_id, party_name, latest_house,
             latest_membership_from, is_current_commons)
         VALUES (4613, 'Alex Burghart', 4, 'Conservative', 1, 'Brentwood and Ongar', true),
                (5030, 'Dr Simon Opher', 15, 'Labour', 1, 'Stroud', true)
         RETURNING id, parliament_member_id"
    )
    .fetch_all(&pool)
    .await?
    .into_iter()
    .map(|member| (member.parliament_member_id, member.id))
    .collect::<HashMap<_, _>>();
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new()?;
    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_declaration_fetcher_config(&tmp);
    fs::write(tmp.path().join(".env"), format!("DATABASE_URL={url}\n"))?;
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(tmp.path())
        .env_remove("DATABASE_URL")
        .args(["data", "declarations", "fetch"])
        .arg(path)
        .args(["--ingestion-key", &ingestion_key.to_string()])
        .output()?;
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let funding = read_declaration_funding(tmp.path(), &ingestion_key)?;

    let individual_donation = funding
        .iter()
        .find(|entry| entry.declaration_id == 16901)
        .context("expected Alex Burghart's donation from David Robert Meller")?;
    assert_eq!(
        individual_donation,
        &DeclarationFunding {
            declaration_id: 16901,
            member_id: members[&4613].to_string(),
            funding_entry: FundingEntry {
                donor_name: Some("David Robert Meller".into()),
                amount: Some("2000.00".into()),
                currency: Some("GBP".into()),
                payment_type: Some("Monetary".into()),
                funder_kind: Some("Individual".into()),
                company_number: None,
            },
        }
    );

    let company_donation = funding
        .iter()
        .find(|entry| entry.declaration_id == 16863)
        .context("expected Simon Opher's donation from Labour Together")?;
    assert_eq!(
        company_donation,
        &DeclarationFunding {
            declaration_id: 16863,
            member_id: members[&5030].to_string(),
            funding_entry: FundingEntry {
                donor_name: Some("Labour Together Limited".into()),
                amount: Some("5000.00".into()),
                currency: Some("GBP".into()),
                payment_type: Some("Monetary".into()),
                funder_kind: Some("Company".into()),
                company_number: Some("09630980".into()),
            },
        }
    );
    Ok(())
}

#[test]
fn database_commands_require_environment_url() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    // An empty .env prevents discovery of configuration from a parent directory.
    fs::write(tmp.path().join(".env"), "")?;
    let config = tmp.path().join("config.yaml");
    fs::write(
        &config,
        "data_dir: ./data\nbatch_size: 100\nconnection_string: obsolete-yaml-url\n",
    )?;

    for args in [
        ["data", "members", "load"],
        ["data", "declarations", "fetch"],
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(tmp.path())
            .env_remove("DATABASE_URL")
            .args(args)
            .arg(&config)
            .output()?;

        assert!(!output.status.success());
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(stderr.contains("DATABASE_URL must be set"), "{stderr}");
    }
    Ok(())
}

