use clap::{Parser, error::ErrorKind};

use super::{DataArgs, DataCommands};

const INGESTION_KEY: &str = "00000000-0000-4000-8000-000000000001";
const INGESTION_COMMANDS: [(&str, &str); 3] = [
    ("members", "fetch"),
    ("members", "load"),
    ("declarations", "fetch"),
];

#[test]
fn fetch_and_load_accept_positional_keys_and_config_options_in_either_order() {
    for (entity, stage) in INGESTION_COMMANDS {
        for option in ["--config", "-c"] {
            for arguments in [
                [
                    "exposed-data",
                    entity,
                    stage,
                    INGESTION_KEY,
                    option,
                    "config.yaml",
                ],
                [
                    "exposed-data",
                    entity,
                    option,
                    "config.yaml",
                    stage,
                    INGESTION_KEY,
                ],
            ] {
                let args = DataArgs::try_parse_from(arguments).unwrap();
                let (config, ingestion_key) = match args.command {
                    DataCommands::Members {
                        config,
                        ingestion_key,
                        ..
                    }
                    | DataCommands::Declarations {
                        config,
                        ingestion_key,
                        ..
                    } => (config, ingestion_key),
                    DataCommands::Latest { .. } => panic!("expected an ingestion command"),
                };
                assert_eq!(config, std::path::PathBuf::from("config.yaml"));
                assert_eq!(ingestion_key.to_string(), INGESTION_KEY);
            }
        }
    }
}

#[test]
fn fetch_and_load_require_an_ingestion_key() {
    for (entity, stage) in INGESTION_COMMANDS {
        let error =
            DataArgs::try_parse_from(["exposed-data", entity, stage, "--config", "config.yaml"])
                .err()
                .unwrap();

        assert_eq!(error.kind(), ErrorKind::MissingRequiredArgument);
        assert!(error.to_string().contains("<INGESTION_KEY>"));
    }
}

#[test]
fn fetch_and_load_reject_invalid_ingestion_keys() {
    for (entity, stage) in INGESTION_COMMANDS {
        let error = DataArgs::try_parse_from([
            "exposed-data",
            entity,
            stage,
            "not-a-uuid",
            "--config",
            "config.yaml",
        ])
        .err()
        .unwrap();

        assert_eq!(error.kind(), ErrorKind::ValueValidation);
        assert!(error.to_string().contains("<INGESTION_KEY>"));
    }
}

#[test]
fn all_data_commands_require_config_as_an_option() {
    for arguments in [
        vec!["exposed-data", "latest"],
        vec!["exposed-data", "members", "fetch", INGESTION_KEY],
        vec!["exposed-data", "members", "load", INGESTION_KEY],
        vec!["exposed-data", "declarations", "fetch", INGESTION_KEY],
    ] {
        let error = DataArgs::try_parse_from(&arguments).err().unwrap();
        assert_eq!(error.kind(), ErrorKind::MissingRequiredArgument);
        assert!(error.to_string().contains("--config <CONFIG>"));

        let mut positional_config = arguments;
        positional_config.push("config.yaml");
        let error = DataArgs::try_parse_from(positional_config).err().unwrap();
        assert_eq!(error.kind(), ErrorKind::UnknownArgument);
    }
}

#[test]
fn latest_accepts_both_config_options_without_an_ingestion_key() {
    for option in ["--config", "-c"] {
        let args =
            DataArgs::try_parse_from(["exposed-data", "latest", option, "config.yaml"]).unwrap();

        let DataCommands::Latest { config } = args.command else {
            panic!("expected the latest command");
        };
        assert_eq!(config, std::path::PathBuf::from("config.yaml"));
    }
}

#[test]
fn unsupported_stages_fail_during_argument_parsing() {
    for (entity, stage) in [("members", "unknown"), ("declarations", "load")] {
        let error = DataArgs::try_parse_from([
            "exposed-data",
            entity,
            stage,
            INGESTION_KEY,
            "--config",
            "config.yaml",
        ])
        .err()
        .unwrap();

        assert_eq!(error.kind(), ErrorKind::ValueValidation);
        assert!(error.to_string().contains("<STAGE>"));
    }
}

